uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;

out vec4 fragColor;

// --- Helper Functions ---

// 2D Rotation Matrix
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Smooth random hash for value noise
vec2 hash22(vec2 p) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
}

// Cubic interpolated value noise 
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix( mix( dot( hash22(i + vec2(0.0,0.0)), f - vec2(0.0,0.0) ), 
                     dot( hash22(i + vec2(1.0,0.0)), f - vec2(1.0,0.0) ), u.x),
                mix( dot( hash22(i + vec2(0.0,1.0)), f - vec2(0.0,1.0) ), 
                     dot( hash22(i + vec2(1.0,1.0)), f - vec2(1.0,1.0) ), u.x), u.y);
}

// Fractional Brownian Motion (High-Fidelity Organic Detail)
float fbm(vec2 x) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    mat2 r = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
    for (int i = 0; i < 5; ++i) {
        v += a * noise(x);
        x = r * x * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}

// HSV to RGB Conversion for Absolute Color Control
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // 2. Timing
    float spd = (u_speed <= 0.0) ? 0.15 : u_speed * 0.5;
    float t = iTime * spd;

    // --- Background (Adaptive Void) ---
    // The background dynamically tints to match your u_color_cycle fader
    vec3 bgTop = hsv2rgb(vec3(u_color_cycle, 0.8, 0.05)); // Extremely dark, saturated base hue
    vec3 bgBottom = vec3(0.01, 0.00, 0.01); // Near pitch black
    vec3 finalColor = mix(bgBottom, bgTop, uv0.y + 0.5);

    // 3. Layer Loop
    float density = (u_layers <= 0.0) ? 3.0 : u_layers;
    float scale = (u_scale <= 0.0) ? 2.5 : u_scale * 3.0; 
    float brightness = (u_intensity <= 0.0) ? 1.5 : u_intensity;

    for(float i = 0.0; i < 4.0; i++) {
        if(i >= density) break;

        // --- Space Setup ---
        vec2 p = uv0 * scale * (1.0 + i * 0.3);
        p.y -= t * 0.2 * (i + 1.0);
        p.x += sin(t * 0.3 + i) * 0.2;
        p *= rot(sin(t * 0.05 + i) * 0.1);

        // --- Domain Warping ---
        vec2 q = vec2(0.0);
        q.x = fbm(p + vec2(0.0, 0.0) + t * 0.1);
        q.y = fbm(p + vec2(5.2, 1.3) - t * 0.15);

        vec2 r = vec2(0.0);
        r.x = fbm(p + 4.0 * q + vec2(1.7, 9.2) + t * 0.2);
        r.y = fbm(p + 4.0 * q + vec2(8.3, 2.8) - t * 0.1);

        // Tissue Fold Height
        float tissueHeight = fbm(p + 4.0 * r);

        // --- High-Fidelity Color & Lighting ---

        // Master Hue Calculation: Anchored by u_color_cycle, with slight organic variance
        float organicHueShift = tissueHeight * 0.1 - i * 0.05;
        float finalHue = fract(u_color_cycle + organicHueShift);

        // Base color mapping via HSV
        vec3 col = hsv2rgb(vec3(finalHue, 0.85, 0.9));

        // Fake Ambient Occlusion (AO): Crushes the shadows in the deep folds for 4K contrast
        float ao = smoothstep(-0.2, 0.6, tissueHeight);
        col *= ao; 

        // Subsurface scattering: Glowing inner warmth
        float subsurface = smoothstep(0.3, 0.0, abs(tissueHeight - 0.4));
        // Shifts the hue slightly towards a warmer/brighter tone for the internal glow
        vec3 glowCol = hsv2rgb(vec3(fract(finalHue + 0.08), 0.6, 1.0)); 
        col += glowCol * subsurface * 1.2;

        // Sharp 4K Specular highlight (Wetness) remains neutral white
        float wetHighlight = pow(max(0.0, sin(r.y * 7.0 + t * 1.5)), 8.0);
        vec3 specColor = vec3(1.0, 0.95, 0.95) * wetHighlight * 1.5;

        // --- Blending ---
        float alpha = smoothstep(0.0, 0.8, tissueHeight);
        float layerFade = 1.0 - (i / 4.0);
        alpha *= layerFade;

        // Additive blending for a luminous, rich effect
        finalColor = mix(finalColor, col * brightness + specColor * brightness, alpha);
    }

    // 5. Post-Processing (Cinematic Grade)
    // Strong vignette
    float vig = 1.0 - length(uv0) * 0.7;
    finalColor *= smoothstep(0.0, 0.8, vig);

    // Contrast Curve
    finalColor = pow(finalColor, vec3(1.3, 1.2, 1.1)); 

    // Prevent clipping artifacts
    finalColor = clamp(finalColor, 0.0, 1.0);

    fragColor = vec4(finalColor, 1.0);
}
